import { useState } from "react";
import { FormField, TreeSelect } from "@godxjp/ui/data-entry";

const accountTree = [
  {
    value: "assets",
    label: "Assets",
    content: [
      { value: "current-assets", label: "Current Assets", content: [
          { value: "cash", label: "Cash" },
          { value: "ar", label: "Accounts Receivable" },
        ],
      },
      { value: "fixed-assets", label: "Fixed Assets", content: [
          { value: "equipment", label: "Equipment" },
        ],
      },
    ],
  },
  {
    value: "liabilities",
    label: "Liabilities",
    content: [
      { value: "ap", label: "Accounts Payable" },
    ],
  },
];

// Single-select (returns string | undefined)
export function AccountPicker() {
  const [account, setAccount] = useState<string | undefined>();
  return (
    <FormField id="account-picker" label="GL Account">
      <TreeSelect
        id="account-picker"
        treeData={accountTree}
        value={account}
        onValueChange={(v) => setAccount(v as string | undefined)}
        showSearch
        treeDefaultExpandAll
        placeholder="Select account…"
        allowClear
      />
    </FormField>
  );
}

// Multi-select with checkboxes + cascade + SHOW_PARENT display
export function DepartmentFilter() {
  const [selected, setSelected] = useState<string[]>([]);
  return (
    <TreeSelect
      id="dept-filter"
      treeData={accountTree}
      value={selected}
      onValueChange={(v) => setSelected(v as string[])}
      treeCheckable
      showCheckedStrategy={TreeSelect.SHOW_PARENT}
      showSearch
      placeholder="Filter by department…"
    />
  );
}
